{
  "positionId": "P04",
  "interviews": [
    {
      "categoryId": "P04-C1",
      "itemId": "P04-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "하중 조건을 부품의 주요 치수 결정으로 연결할 수 있는지 검증한다. 감속기 축 지름을 최종적으로 정한 이유에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "교재에 주어진 하중 조건으로 감속기 축 지름을 선정한 개인 과제의 상황을 설명한다.",
          "task": "주어진 하중을 견디는 축 지름을 결정해야 했던 요구를 설명한다.",
          "action": "축 지름 결정에 지배적으로 작용한 하중이나 설계 조건을 짚고, 이를 계산값과 최종 선정 지름에 연결해 설명한다.",
          "result": "선정한 지름이 해당 하중 조건에서 필요한 강도나 안전 여유를 확보한다고 판단한 내용을 제시한다. 실제 제작이나 시험 결과는 요구하지 않는다."
        },
        "expectedEvidence": [
          "축 지름을 해당 값으로 결정한 핵심 이유",
          "그 이유를 뒷받침하는 과제의 하중 조건과 축에 하중이 전달되는 방식",
          "하중에 따른 계산 또는 검토 내용과 선정 지름 사이의 연결",
          "선정 지름이 요구 조건을 충족한다고 판단한 설명"
        ]
      },
      "question": "‘기계요소설계 수업 과제: 감속기 축 설계 계산’에서 축 지름을 선정하셨던데요, 그 지름으로 정하신 결정적인 이유는 무엇이었어요?",
      "answerTip": "기억나는 장면을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "축 지름을 결정한 핵심 이유를 과제의 실제 하중 조건에 근거해 구체적으로 설명한다.",
            "축에 전달되는 하중이 계산이나 검토에 반영되어 최종 지름으로 이어진 관계가 명확하다.",
            "선정 지름이 필요한 강도나 안전 여유를 충족한다고 판단한 설명이 기술적으로 타당하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "축 지름 결정 이유를 하중이나 강도 조건과 연결하지만, 계산 또는 최종 선정값과의 연결은 일부 불명확하다.",
            "선정 지름이 요구 조건을 충족한다는 설명은 있으나 이를 뒷받침하는 검토 내용이 제한적이다."
          ]
        },
        "poor": {
          "criteria": [
            "선정 지름이나 공식만 언급하고 해당 지름으로 정한 이유를 설명하지 못한다.",
            "설명한 하중 조건과 지름 결정 사이의 연결이 없거나 기술적으로 모순된다."
          ]
        }
      }
    },
    {
      "categoryId": "P04-C1",
      "itemId": "P04-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "기능에 필요한 치수에 적절한 공차를 지정할 수 있는지 검증한다. 감속기 회전축의 베어링 끼워맞춤부에 적용할 치수 공차 선택에 초점을 둔다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "감속기 회전축의 3D 모델을 제작용 양산 도면으로 옮기는 상황이다.",
          "task": "베어링 끼워맞춤부가 기능에 맞게 제작되도록 해당 부위의 치수 공차를 지정해야 한다.",
          "action": "공차 선택에 필요한 끼워맞춤 조건을 명시하고, 그 조건에 적합한 공차역이나 허용차 표기 방안을 제시한다.",
          "result": "제안한 공차가 베어링 결합 기능을 확보하면서 불필요하게 가공 정밀도를 높이지 않는 이유를 설명한다. 실제 제작 결과나 수치가 없는 상태에서의 확정 허용차는 요구하지 않는다."
        },
        "expectedEvidence": [
          "베어링 끼워맞춤부에 지정할 치수 공차의 구체적인 제안",
          "공차 선택의 전제가 되는 베어링 결합 조건",
          "제안한 공차가 필요한 끼워맞춤 기능에 적합한 이유",
          "기능상 필요한 정밀도와 가공 가능성을 연결한 설명"
        ]
      },
      "question": "감속기 회전축의 3D 모델을 양산 도면으로 옮기는 상황이라고 해 볼게요. 베어링 끼워맞춤부에는 어떤 치수 공차를 지정하시겠어요?",
      "answerTip": "생각을 정리한 뒤 차근차근 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "베어링 결합 조건을 명확히 전제하고 이에 맞는 공차역이나 허용차 표기 방안을 구체적으로 제시한다.",
            "제안한 공차가 필요한 끼워맞춤 기능을 확보하는 이유가 기술적으로 타당하다.",
            "필요한 정밀도를 확보하되 불필요한 가공 부담을 피하는 선택임을 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "적용할 공차 방향이나 공차역을 제안하고 베어링 결합 기능과 연결한다.",
            "결합 조건의 전제 또는 가공 정밀도에 대한 설명이 제한적이지만, 제안 자체에 뚜렷한 기술적 모순은 없다."
          ]
        },
        "poor": {
          "criteria": [
            "적용할 공차를 제안하지 않고 공차의 일반적인 정의만 설명한다.",
            "결합 조건과 무관하게 무조건 좁은 공차를 제시하거나, 제안한 공차가 설명한 끼워맞춤 기능과 모순된다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P14",
  "interviews": [
    {
      "categoryId": "P14-C1",
      "itemId": "P14-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "양산 준비를 위한 설비 배치 판단이 공정 흐름과 생산 조건에 근거했는지 검증한다. 지원자가 작성한 배치안에서 설비 위치를 정한 판단 기준 하나에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "신규 차종 도어 트림 조립 라인의 배치안을 작성하던 상황과 위치 검토가 필요했던 설비가 제시된다.",
          "task": "담당한 배치안 작성 범위에서 해당 설비의 위치를 결정할 기준을 정해야 했다는 점이 드러난다.",
          "action": "작업 순서, 공정별 사이클 타임, 작업자 동선, 목표 생산량 중 실제 판단에 사용한 조건을 바탕으로 설비 위치를 정한 기준을 설명한다.",
          "result": "설명한 기준이 작성한 배치안의 설비 위치에 어떻게 반영됐는지 드러난다. 양산 실적이나 설비 구매 결정까지 제시할 필요는 없다."
        },
        "expectedEvidence": [
          "설비 위치를 정할 때 실제로 적용한 구체적인 판단 기준",
          "해당 기준이 필요했던 공정 흐름이나 생산 조건",
          "판단 기준과 작성한 배치안의 설비 위치 사이의 연결"
        ]
      },
      "question": "신규 차종 도어 트림 조립 라인 양산 준비에서 라인 배치안을 작성하셨던데요, 그때 설비 위치를 정한 판단 기준은 무엇이었어요?",
      "answerTip": "기억에 남는 한 장면을 중심으로 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "설비 위치를 정한 판단 기준을 구체적으로 제시하고, 해당 기준이 공정 흐름이나 생산 조건에 적합했던 이유를 설명한다.",
            "그 기준이 실제 배치안의 설비 위치에 반영된 내용을 설명해 판단과 설계의 연결이 확인된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "동선 단축이나 공정 간 시간 균형처럼 직무에 타당한 기준을 제시하지만, 당시 조건에 대한 설명이 제한적이다.",
            "기준을 배치안에 적용했다고 설명하나 실제 설비 위치와의 연결이 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "설비 위치를 정한 기준을 제시하지 못하거나 배치안을 작성했다는 사실만 반복한다.",
            "제시한 기준이 당시 공정 흐름이나 생산 조건과 연결되지 않아 배치 판단의 타당성을 확인하기 어렵다."
          ]
        }
      }
    },
    {
      "categoryId": "P14-C1",
      "itemId": "P14-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "현장에서 확인된 조립 문제를 작업자가 실행할 수 있는 작업 지시로 작성했는지 검증한다. 작업 표준서에 실제로 작성한 지시 문구 하나에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "도람화성의 신규 차종 조립 라인 시생산에서 발생해 작업 표준서 초판에 반영한 조립 문제 하나가 제시된다.",
          "task": "해당 문제와 관련해 작업자가 수행할 작업을 표준서의 지시 문구로 명확히 작성해야 했다는 점이 드러난다.",
          "action": "실제로 작성한 문구 또는 그 내용을 충실하게 재현해, 작업 대상과 수행 동작 및 해당 작업에 필요한 조건을 표현한 방식을 보여 준다.",
          "result": "제시한 문구에서 작업자가 해야 할 행동을 구체적으로 파악할 수 있다. 문구 적용 후의 불량 감소나 교육 성과는 필수로 요구하지 않는다."
        },
        "expectedEvidence": [
          "조립 문제 하나에 대해 작업 표준서에 실제로 작성한 작업 지시 문구 또는 그에 준하는 구체적인 내용",
          "해당 문구가 다루는 조립 문제와 지시 내용의 연결",
          "작업 대상과 수행 동작이 명확하고, 필요한 작업 조건이 모호하지 않게 표현된 내용"
        ]
      },
      "question": "도람화성에서 시생산 2회의 조립 문제를 작업 표준서 초판에 반영하셨던데요, 그중 한 문제에 대한 작업 지시 문구를 실제로 어떻게 쓰셨어요?",
      "answerTip": "당시 내용을 떠올려 본인 말로 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제 작성한 지시 문구나 그에 준하는 내용을 구체적으로 제시하며, 해당 조립 문제와의 연결이 명확하다.",
            "작업 대상과 수행 동작, 필요한 작업 조건이 분명해 작업자가 무엇을 해야 하는지 문구 자체로 파악할 수 있다."
          ]
        },
        "acceptable": {
          "criteria": [
            "실제로 작성한 지시 내용을 제시하고 조립 문제와의 관련성도 드러난다.",
            "수행할 행동은 이해되지만 작업 대상이나 필요한 조건의 표현이 일부 모호해 추가 설명이 필요하다."
          ]
        },
        "poor": {
          "criteria": [
            "표준서를 작성하거나 개정했다는 사실만 설명하고 실제 지시 내용을 제시하지 못한다.",
            "제시한 내용이 '주의해서 작업한다' 같은 추상적 표현에 머물러 작업자가 수행할 행동을 파악하기 어렵거나 해당 조립 문제와 연결되지 않는다."
          ]
        }
      }
    }
  ]
}
